/* Severity discipline lives here, and it matters more than it looks.

   A "stop" is the pipeline WORKING: it found something it will not guess about
   and asked. If routine stops arrive looking like failures, real failures stop
   being alarming, and the whole point of having a distinct exit code 10 is
   lost. So: amber, and the words "awaiting a decision". Red is reserved for
   fail, and nothing else earns it. */

const inp = $input.first().json;

const SEVERITIES = {
  info: { colour: '#2E7D32', icon: '✔', word: '' },
  stop: { colour: '#E8A33D', icon: '⏸', word: 'awaiting a decision' },
  fail: { colour: '#D14343', icon: '✘', word: 'FAILED' },
};
const severity = SEVERITIES[inp.severity] ? inp.severity : 'info';
const sev = SEVERITIES[severity];

const month = String(inp.month ?? '').trim() || '(month unknown)';
const runId = String(inp.runId ?? '').trim() || '(no runId)';
const stage = String(inp.stage ?? '').trim();
const title = String(inp.title ?? '').trim() || (severity === 'fail' ? 'Pipeline failed' : 'Pipeline update');
const body = String(inp.body ?? '').trim();
const resumeUrl = String(inp.resumeUrl ?? '').trim();
const executionUrl = String(inp.executionUrl ?? '').trim();
const attachments = String(inp.attachments ?? '').trim();

/* The first ~10 lines only. A stderr tail can be thousands of lines and Slack
   will silently truncate the message — better to cut it deliberately and say
   how much was cut than to have Slack decide where the story ends. */
const lines = body ? body.split('\n') : [];
const shown = lines.slice(0, 10).join('\n');
const more = lines.length > 10 ? '\n… ' + (lines.length - 10) + ' more line(s) — see the execution' : '';

const headline = sev.icon + ' RBL ' + month + (sev.word ? ' — ' + sev.word : '') + ': ' + title;

const fields = [
  { type: 'mrkdwn', text: '*Month*\n' + month },
  { type: 'mrkdwn', text: '*Run*\n`' + runId + '`' },
];
if (stage) fields.push({ type: 'mrkdwn', text: '*Stage*\n' + stage });
fields.push({ type: 'mrkdwn', text: '*Severity*\n' + severity });

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: headline.slice(0, 150), emoji: true } },
  { type: 'section', fields },
];
if (shown) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '```' + (shown + more).slice(0, 2800) + '```' } });

/* A stop is only actionable if the person reading it can act. The resume URL is
   the whole difference between "a decision is needed" and "someone must go and
   find where to make it". */
const links = [];
if (resumeUrl) links.push('<' + resumeUrl + '|Make the decision>');
if (executionUrl) links.push('<' + executionUrl + '|Open the execution>');
if (links.length) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: links.join('   ·   ') }] });

/* Colour comes from the attachment wrapper — Block Kit itself has no colour. */
const slackPayload = { attachments: [{ color: sev.colour, blocks }] };

const emailSubject = 'RBL ' + month + ' — ' + (severity === 'fail' ? 'FAILED: ' : severity === 'stop' ? 'awaiting a decision: ' : '') + title;
const emailBody = [
  headline,
  '',
  'Month:    ' + month,
  'Run:      ' + runId,
  stage ? 'Stage:    ' + stage : null,
  'Severity: ' + severity,
  '',
  body || '(no detail)',
  '',
  resumeUrl ? 'DECIDE HERE: ' + resumeUrl : null,
  executionUrl ? 'Execution:   ' + executionUrl : null,
  severity === 'stop'
    ? '\nThis is not a failure. The pipeline stopped because it will not guess, and\nnothing before this point has to be repeated when you resume.'
    : null,
].filter((l) => l !== null).join('\n');

/* Both channels are optional. A notifier that fails when Slack is unset would
   take down the Error Handler that calls it, which is the one path that must
   never go quiet. */
const slackWebhook = $vars.RBL_SLACK_WEBHOOK || '';
const emailTo = $vars.RBL_NOTIFY_TO || '';

return [{
  json: {
    severity, month, runId, stage, title, body, resumeUrl, executionUrl, attachments,
    colour: sev.colour,
    hasSlack: !!slackWebhook,
    hasEmail: !!emailTo,
    emailTo,
    slackWebhook,
    slackPayload,
    emailSubject,
    emailBody,
    json: inp.json ?? null,
  },
}];

/* What actually went out. The Error Handler and the Orchestrator both read
   this: a notification that silently reached nobody is worse than one that
   failed loudly, because the run then looks reported when it is not. */
const f = $('Format').first().json;

let slackOk = null;
if (f.hasSlack) {
  try {
    const s = $('Post to Slack').first().json;
    slackOk = !(s && (s.error || s.ok === false));
  } catch (e) {
    slackOk = false;
  }
}

let emailOk = null;
if (f.hasEmail) {
  try {
    const e = $('Send email').first().json;
    emailOk = !(e && e.error);
  } catch (e) {
    emailOk = false;
  }
}

const delivered = [f.hasSlack && slackOk ? 'slack' : null, f.hasEmail && emailOk ? 'email' : null].filter(Boolean);

return [{
  json: {
    ok: delivered.length > 0,
    severity: f.severity,
    month: f.month,
    runId: f.runId,
    title: f.title,
    delivered,
    slack: f.hasSlack ? (slackOk ? 'sent' : 'FAILED') : 'not configured (RBL_SLACK_WEBHOOK unset)',
    email: f.hasEmail ? (emailOk ? 'sent' : 'FAILED') : 'not configured (RBL_NOTIFY_TO unset)',
    nobodyWasTold: delivered.length === 0,
  },
}];
